CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, full_name text NOT NULL, phone text DEFAULT '', role text NOT NULL DEFAULT 'tenant' CHECK(role IN ('tenant','manager','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS managers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), business_name text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manager_id uuid NOT NULL REFERENCES managers(id), property_name text NOT NULL, address text NOT NULL, total_units integer NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), unit_number text NOT NULL, monthly_rent numeric(12,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'available', UNIQUE(property_id,unit_number));
CREATE TABLE IF NOT EXISTS households (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid UNIQUE NOT NULL REFERENCES units(id), name text NOT NULL);
CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), manager_id uuid REFERENCES managers(id), household_id uuid REFERENCES households(id), status text NOT NULL DEFAULT 'pending', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS rent (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), amount_due numeric(12,2) NOT NULL CHECK(amount_due>=0), due_date date NOT NULL, status text NOT NULL DEFAULT 'unpaid', created_at timestamptz DEFAULT now(), UNIQUE(tenant_id,due_date));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rent_id uuid NOT NULL REFERENCES rent(id), tenant_id uuid NOT NULL REFERENCES tenants(id), amount numeric(12,2) NOT NULL CHECK(amount>0), payment_date timestamptz NOT NULL DEFAULT now(), payment_method text NOT NULL DEFAULT 'manual', reference text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS chores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), assigned_tenant_id uuid REFERENCES tenants(id), title text NOT NULL, due_date date, status text NOT NULL DEFAULT 'pending', completed_at timestamptz);
CREATE TABLE IF NOT EXISTS announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid REFERENCES households(id), manager_id uuid REFERENCES managers(id), title text NOT NULL, body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, amount numeric(12,2) NOT NULL CHECK(amount>0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS expense_splits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES expenses(id), tenant_id uuid NOT NULL REFERENCES tenants(id), amount numeric(12,2) NOT NULL CHECK(amount>=0), UNIQUE(expense_id,tenant_id));
CREATE INDEX IF NOT EXISTS idx_tenants_manager ON tenants(manager_id);
CREATE INDEX IF NOT EXISTS idx_rent_tenant ON rent(tenant_id);
CREATE INDEX IF NOT EXISTS idx_payments_rent ON payments(rent_id);
CREATE INDEX IF NOT EXISTS idx_chores_household ON chores(household_id);
